253	            }
254	        }
255	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
256	    }
257	
258	    /**
259	     * Loads the owner with the given id and, when it exists, produces the response through
260	     * {@code action}; when no such owner exists a {@code 404 Not Found} is returned instead. The
261	     * single-owner endpoints share this "find the owner or report 404" preamble, so the lookup and
262	     * the not-found response are written in exactly one place rather than copied into each method.
263	     *
264	     * @param ownerId the id of the owner to load
265	     * @param action builds the response for an existing owner
266	     * @param <T> the response body type
267	     * @return the result of {@code action} for an existing owner, otherwise a 404 response
268	     */
269	    private <T> ResponseEntity<T> withOwner(Integer ownerId, Function<Owner, ResponseEntity<T>> action) {
270	        Owner owner = this.clinicService.findOwnerById(ownerId);
271	        if (owner == null) {
272	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
273	        }
274	        return action.apply(owner);
275	    }
276	
277	    /**
278	     * Maps a persisted owner to its {@link OwnerDto} and populates the read-only fields that are
279	     * derived from server-side state rather than stored columns (the {@code bulkSignupWarning} flag
280	     * and the {@code identityKey}). Both the create endpoint and the single-owner read endpoint
281	     * return their owner through this method, so an owner is decorated identically on either path
282	     * and each derived field is computed in exactly one place.
283	     *
284	     * @param owner the persisted owner to represent
285	     * @return the owner DTO with its derived read-only fields populated
286	     */
287	    private OwnerDto toOwnerDtoWithDerivedFields(Owner owner) {
288	        owner.setHouseholdSize(householdSize(owner));
289	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
290	        ownerDto.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
291	        ownerDto.setIdentityKey(identityKey(owner));
292	        Integer possibleDuplicateOf = owner.getPossibleDuplicateOf();
293	        ownerDto.setPossibleDuplicate(possibleDuplicateOf != null);
294	        ownerDto.setPossibleDuplicateOf(possibleDuplicateOf);
295	        return ownerDto;
296	    }
297	
298	    /**
299	     * Canonicalizes the submitted address in place before it is validated, stored and returned, so
300	     * every later step - the required-field check, the persisted value and the response - sees the
301	     * single normalized form produced by {@link AddressNormalizer#normalize(String)} (see that method
302	     * for the trim/collapse/upper-case/abbreviation rules). Normalizing once here, at the head of the
303	     * create flow, keeps address canonicalization in exactly one place rather than spread across the
304	     * steps that read the address.
305	     *
306	     * <p>An address may be supplied either as the structured {@code addressLine1} (with an optional
307	     * {@code addressLine2}) or as the single flat {@code address}, the latter kept for backward
308	     * compatibility. Whichever address fields are supplied are normalized, and the structured fields
309	     * are preferred when present: the flat {@code address} returned is composed as the normalized
310	     * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended when an
311	     * {@code addressLine2} is present; only when no {@code addressLine1} is supplied does the flat
312	     * {@code address} retain its own normalized value.
313	     *
314	     * @param ownerFieldsDto the submitted owner fields, whose address fields are replaced with their normalized form
315	     */
316	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
317	        String addressLine1 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
318	        String addressLine2 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
319	        String flatAddress = addressNormalizer.normalize(ownerFieldsDto.getAddress());
320	        ownerFieldsDto.setAddressLine1(addressLine1);
321	        ownerFieldsDto.setAddressLine2(addressLine2);
322	        if (addressLine1 != null && !addressLine1.isBlank()) {
323	            String composed = addressLine2 != null && !addressLine2.isBlank()
324	                ? addressLine1 + " " + addressLine2
325	                : addressLine1;
326	            ownerFieldsDto.setAddress(composed);
327	        } else {
328	            ownerFieldsDto.setAddress(flatAddress);
329	        }
330	    }
331	
332	    /**
333	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
334	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
335	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
336	     * blank (e.g. {@code "   "}). The offending field names are reported through an
337	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
338	     * as a 400 response carrying an {@code errors} array of field names.
339	     *
340	     * @param ownerFieldsDto the submitted owner fields
341	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
342	     */
343	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
344	        List<String> blankFields = new ArrayList<>();
345	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
346	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
347	        addRequiredAddress(blankFields, ownerFieldsDto);
348	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
349	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
350	        if (!blankFields.isEmpty()) {
351	            throw new InvalidOwnerFieldsException(blankFields);
352	        }
353	    }
354	
355	    private void addIfBlank(List<String> blankFields, String field, String value) {
356	        if (value != null && value.isBlank()) {
357	            blankFields.add(field);
358	        }
359	    }
360	
361	    /**
362	     * Records the address requirement's offending field name(s) into {@code blankFields}. An owner
363	     * must supply an address in EITHER accepted form: the structured {@code addressLine1} or the flat
364	     * {@code address} (kept for backward compatibility). The requirement is satisfied when at least one
365	     * of those is present and non-blank; only when both are missing or blank is {@code address} reported
366	     * as the offending field. Holding the "an owner must have an address" rule in its own method - rather
367	     * than a bare entry in the field list - gives it one place to live as the accepted address forms grow.
368	     *
369	     * @param blankFields the accumulating list of blank required-field names
370	     * @param ownerFieldsDto the submitted owner fields
371	     */
372	    private void addRequiredAddress(List<String> blankFields, OwnerFieldsDto ownerFieldsDto) {
373	        if (isBlank(ownerFieldsDto.getAddressLine1()) && isBlank(ownerFieldsDto.getAddress())) {
374	            blankFields.add("address");
375	        }
376	    }
377	
378	    private boolean isBlank(String value) {
379	        return value == null || value.isBlank();
380	    }
