432	    /**
433	     * Builds the {@code customerCode} assigned to a newly created owner, formatted
434	     * {@code '<REGION>-<HASH8>'}: {@code REGION} is the owner's canonical region code resolved from
435	     * its {@code postcode} (falling back to its {@code city}) through the shared
436	     * {@link Region#code(String, String)}, and {@code HASH8} is the first 8 upper-case hex characters
437	     * of the SHA-256 digest of the owner's normalized telephone followed by its last name
438	     * (e.g. {@code 'NSW-1A2B3C4D'}). When this base code collides with an existing owner's
439	     * {@code customerCode}, {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that
440	     * makes the result unique (e.g. {@code 'NSW-1A2B3C4D-2'}), so distinct owners always receive
441	     * distinct customer codes.
442	     *
443	     * @param owner the owner being created, with its telephone already normalized
444	     * @return the formatted, de-duplicated customer code
445	     */
446	    private String customerCode(Owner owner) {
447	        String region = Region.code(owner.getPostcode(), owner.getCity());
448	        String hash8 = hashPrefix(owner.getTelephone() + owner.getLastName(), CUSTOMER_CODE_HASH_LENGTH);
449	        String base = region + "-" + hash8;
450	        return deduplicateCustomerCode(base);
451	    }
