453	    /**
454	     * Ensures the given base {@code customerCode} does not collide with an existing owner's
455	     * {@code customerCode}. When no existing owner carries the base code it is returned unchanged;
456	     * otherwise {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that yields a code
457	     * held by no existing owner.
458	     *
459	     * @param base the computed base customer code, formatted {@code '<REGION>-<HASH8>'}
460	     * @return the base code, or a {@code '<base>-<n>'} variant that is unique among existing owners
461	     */
462	    private String deduplicateCustomerCode(String base) {
463	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
464	            .map(Owner::getCustomerCode)
465	            .filter(java.util.Objects::nonNull)
466	            .collect(java.util.stream.Collectors.toSet());
467	        if (!existing.contains(base)) {
468	            return base;
469	        }
470	        int n = 2;
471	        while (existing.contains(base + "-" + n)) {
472	            n++;
473	        }
474	        return base + "-" + n;
475	    }
