570	    /**
571	     * Adjusts a date so it falls on a business day. A Saturday is rolled forward to the following
572	     * Monday and a Sunday to the next day (Monday); any weekday is returned unchanged. Applied to
573	     * the effective registration date so that a weekend value - whether supplied in the request or
574	     * defaulted to the server date - is stored as the next Monday, and every value derived from the
575	     * registration date (such as the membership number's year segment and the daily create-limit
576	     * bucket) uses the adjusted business day.
577	     *
578	     * @param date the effective registration date
579	     * @return the same date when it is a weekday, otherwise the next Monday
580	     */
581	    private LocalDate businessDay(LocalDate date) {
582	        DayOfWeek dayOfWeek = date.getDayOfWeek();
583	        if (dayOfWeek == DayOfWeek.SATURDAY) {
584	            return date.plusDays(2);
585	        }
586	        if (dayOfWeek == DayOfWeek.SUNDAY) {
587	            return date.plusDays(1);
588	        }
589	        return date;
