692	    /**
693	     * Computes the soft-match {@code possibleDuplicateOf} for a newly created owner: the id of the
694	     * first existing owner that shares this owner's {@code lastName} (compared case-insensitively) and
695	     * {@code postcode} while carrying a <em>different</em> telephone (compared by canonical E.164 form,
696	     * see {@link TelephoneNormalizer#canonicalize(String)}), or {@code null} when no such owner exists.
697	     * The check runs only after the exact-identity duplicate check ({@link #rejectDuplicateIdentity(Owner)})
698	     * has passed, so a shared last-name-and-postcode with the same telephone has already been rejected as
699	     * a hard duplicate and can never surface here. A blank {@code postcode} never matches, since two
700	     * owners without a postcode do not share one. The captured id is stored on the new owner and surfaced
701	     * as the read-only {@code possibleDuplicate} / {@code possibleDuplicateOf} fields.
702	     *
703	     * @param owner the fully-populated owner being created (telephone normalized)
704	     * @return the id of the first soft-matching existing owner, or {@code null} when none matches
705	     */
706	    private Integer possibleDuplicateOf(Owner owner) {
707	        if (owner.getPostcode() == null || owner.getPostcode().isBlank()) {
708	            return null;
709	        }
710	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
711	        return this.clinicService.findAllOwners().stream()
712	            .filter(existing -> equalsIgnoreCase(existing.getLastName(), owner.getLastName())
713	                && owner.getPostcode().equals(existing.getPostcode())
714	                && !java.util.Objects.equals(telephone, telephoneNormalizer.canonicalize(existing.getTelephone())))
715	            .map(Owner::getId)
716	            .filter(java.util.Objects::nonNull)
717	            .findFirst()
718	            .orElse(null);
