736	        String normalizedEmail = emailNormalizer.normalize(owner.getEmail());
737	        String email = normalizedEmail == null ? "" : normalizedEmail;
738	        String household = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
739	        return telephone + "|" + email + "|" + household;
