750	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
751	     * @param key the canonical key of the owner being created
752	     * @return the first existing owner sharing the key, or empty when none does
753	     */
754	    private Optional<Owner> findExistingOwner(Function<Owner, String> keyExtractor, String key) {
755	        return this.clinicService.findAllOwners().stream()
756	            .filter(owner -> key.equals(keyExtractor.apply(owner)))
757	            .findFirst();
