847	    /**
848	     * Number of leading hex characters of the household hash retained as the shared
849	     * {@code householdId}.
850	     */
851	    private static final int HOUSEHOLD_ID_LENGTH = 12;
852	
853	    /**
854	     * Computes the leading {@code length} upper-case hex characters of the SHA-256 digest of the
855	     * UTF-8 bytes of {@code input}. This is the shared hashing primitive behind the derived
856	     * identifiers that fingerprint owner fields - such as the household-scoped {@code householdId} -
857	     * so every such identifier is produced by the same algorithm and differs only in the value it
858	     * hashes and the number of hex characters it keeps.
859	     *
860	     * @param input the value to hash
861	     * @param length the number of leading hex characters to keep
862	     * @return the leading {@code length} upper-case hex characters of the SHA-256 digest
863	     */
864	    private String hashPrefix(String input, int length) {
865	        try {
866	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
867	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
868	            StringBuilder sb = new StringBuilder(digest.length * 2);
869	            for (byte b : digest) {
870	                sb.append(String.format("%02X", b));
871	            }
872	            return sb.substring(0, length);
873	        } catch (java.security.NoSuchAlgorithmException e) {
874	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
875	        }
876	    }
877	}
